function validate(input) {
  const [{ Flights = [], Passengers = [] }] = input;
  const flights = new Set(), passengers = new Set(), slots = new Set();
  for (const [id, capacity] of Flights) {
    if (id === null || capacity === null) return 'Flights cannot hold nulls.';
    if (flights.has(id)) return `flight_id ${id} appears twice.`;
    if (capacity < 0) return 'capacity cannot be negative.';
    flights.add(id);
  }
  for (const [id, flight, time] of Passengers) {
    if (id === null || flight === null || time === null) return 'Passengers cannot hold nulls.';
    if (passengers.has(id)) return `passenger_id ${id} appears twice.`;
    passengers.add(id);
    if (!flights.has(flight)) return `Flight ${flight} is not in Flights.`;
    if (!/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}$/.test(time)) return `${time} is not a datetime.`;
    if (slots.has(`${flight}|${time}`)) return `Two bookings on flight ${flight} share ${time}.`;
    slots.add(`${flight}|${time}`);
  }
  return null;
}

