function generate(rand, size) {
  const small = size === 'small';
  const flightCount = small ? 1 + Math.floor(rand() * 3) : 120;
  const Flights = [];
  for (let id = 1; id <= flightCount; id++) Flights.push([id, small ? Math.floor(rand() * 4) : 5 + Math.floor(rand() * 20)]);
  const want = small ? Math.floor(rand() * 9) : 1900;
  const pad = n => String(n).padStart(2, '0');
  const used = new Set(), bookings = [];
  for (let tries = 0; bookings.length < want && tries < want * 20; tries++) {
    const flight = 1 + Math.floor(rand() * flightCount);
    const day = small ? 9 + Math.floor(rand() * 2) : 1 + Math.floor(rand() * 20);
    const hour = small ? 8 + Math.floor(rand() * 4) * 3 : Math.floor(rand() * 24);
    const minute = small ? 0 : Math.floor(rand() * 60);
    const time = `2023-07-${pad(day)} ${pad(hour)}:${pad(minute)}:00`;
    if (used.has(`${flight}|${time}`)) continue;
    used.add(`${flight}|${time}`);
    bookings.push([flight, time]);
  }
  // Passenger ids are handed out in a shuffled order, so they say nothing about booking order.
  const ids = bookings.map((_, i) => 101 + i);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Passengers = bookings.map(([flight, time], i) => [ids[i], flight, time]);
  return [{ Flights, Passengers }];
}
